def classify_territory(text: str) -> str:
    text_lower = text.lower()
    scores = defaultdict(int)
    for territory, keywords in TERRITORY_KEYWORDS.items():
        for kw in keywords:
            if kw in text_lower:
                scores[territory] += 1
    if not scores:
        return "General / unclassified"
    return max(scores.items(), key=lambda x: x[1])[0]


